def add_itr_income_heads(apps, schema_editor):
    ServiceCategory = apps.get_model("whatsapp_bot", "ServiceCategory")
    ServicePricing = apps.get_model("whatsapp_bot", "ServicePricing")

    category, _ = ServiceCategory.objects.get_or_create(
        category_code="itr",
        defaults={"display_name": "ITR Filing", "order": 0},
    )
    codes = [item["service_code"] for item in ITR_INCOME_HEADS]
    # Preserve old records for reporting, but prevent previous ITR products
    # from appearing alongside this purpose-built income-head catalogue.
    ServicePricing.objects.filter(category=category).exclude(service_code__in=codes).update(is_active=False)

    for item in ITR_INCOME_HEADS:
        defaults = {**item, "category": category, "is_active": True}
        ServicePricing.objects.update_or_create(service_code=item["service_code"], defaults=defaults)


def remove_itr_income_heads(apps, schema_editor):
    ServicePricing = apps.get_model("whatsapp_bot", "ServicePricing")
    ServicePricing.objects.filter(service_code__in=[item["service_code"] for item in ITR_INCOME_HEADS]).delete()


